import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 외부 자산실사 시스템 호출 방식이 입력에 없어, 연계 대상(실사 결과 행)이 있으면 성공, 없으면 실패로 처리한다.
// 가정: 연계 실패는 502로 거절하며 이 요청의 연계 이력은 함께 되돌려진다.

function textOf(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return String(value);
}

@Controller('api/v1')
export class FnSfr02505Controller {
  @Post('/asset-inspection-plans/:assetInspectionPlanId/link')
  @HttpCode(200)
  async linkAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const planId = req.params['assetInspectionPlanId'];
    if (!/^\d+$/.test(planId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '실사계획 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const plans = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:planId AS bigint)',
        { planId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'ASSET_INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
      }
      if (plans[0].approvalStatus !== '승인') {
        throw new ApiError(409, 'ASSET_INSPECTION_PLAN_NOT_APPROVED', '승인되지 않은 계획은 실사를 처리할 수 없습니다.');
      }
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM asset_inspection_item WHERE asset_inspection_plan_id = CAST(:planId AS bigint)',
        { planId },
      );
      const total = Number(counts[0].total);
      const logs = await db.query(
        'INSERT INTO link_log (requester_id, link_target, status, requested_at, created_at, updated_at) '
          + "VALUES (CAST(:userId AS bigint), 'ASSET_INSPECTION', 'REQUESTED', now(), now(), now()) "
          + 'RETURNING link_log_id AS "linkLogId"',
        { userId: user.id },
      );
      const linkLogId = logs[0].linkLogId;
      if (total === 0) {
        const reason = '연계할 실사 대상이 없어 외부 자산실사 시스템 연계에 실패했습니다.';
        await db.execute(
          "UPDATE link_log SET status = 'FAILED', failure_reason = :reason, completed_at = now(), updated_at = now() "
            + 'WHERE link_log_id = :linkLogId',
          { reason, linkLogId },
        );
        throw new ApiError(502, 'ASSET_INSPECTION_LINK_FAILED', reason);
      }
      await db.execute(
        "UPDATE link_log SET status = 'SUCCESS', processed_count = :total, completed_at = now(), updated_at = now() "
          + 'WHERE link_log_id = :linkLogId',
        { total, linkLogId },
      );
      return { linkStatus: 'SUCCESS', failureReason: null };
    });
  }

  @Post('/asset-inspection-items/receive')
  @HttpCode(200)
  async receiveAssetInspectionResults(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const data = checks.inputOf(req.body);
    const planId = textOf(data['assetInspectionPlanId']);
    const assetId = textOf(data['assetId']);
    if (planId === null || !/^\d+$/.test(planId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산실사 계획 ID를 확인해 주세요.');
    }
    if (assetId === null || !/^\d+$/.test(assetId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산 ID를 확인해 주세요.');
    }
    const inspectionResult = textOf(data['inspectionResult']);
    if (inspectionResult !== null && inspectionResult.length > 20) {
      throw new ApiError(400, 'VALIDATION_FAILED', '실사 결과는 20자 이내로 입력해 주세요.');
    }
    const inspectedAt = textOf(data['inspectedAt']);
    if (inspectedAt !== null && !/^\d{4}-\d{2}-\d{2}/.test(inspectedAt)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '실사 일시 형식이 올바르지 않습니다.');
    }
    const remark = textOf(data['remark']);
    return transaction(async (db) => {
      const plans = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:planId AS bigint)',
        { planId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'ASSET_INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
      }
      if (plans[0].approvalStatus !== '승인') {
        throw new ApiError(409, 'ASSET_INSPECTION_PLAN_NOT_APPROVED', '승인되지 않은 계획의 결과는 저장할 수 없습니다.');
      }
      const items = await db.query(
        'SELECT asset_inspection_item_id AS "assetInspectionItemId" FROM asset_inspection_item '
          + 'WHERE asset_inspection_plan_id = CAST(:planId AS bigint) AND asset_id = CAST(:assetId AS bigint)',
        { planId, assetId },
      );
      if (items.length === 0) {
        throw new ApiError(422, 'ASSET_NOT_IN_INSPECTION_PLAN', '자산이 없거나 실사 대상이 아닙니다.');
      }
      const itemId = items[0].assetInspectionItemId;
      await db.execute(
        'UPDATE asset_inspection_item SET inspection_result = :inspectionResult, '
          + 'inspected_at = CAST(:inspectedAt AS timestamptz), remark = :remark, updated_at = now() '
          + 'WHERE asset_inspection_item_id = :itemId',
        { inspectionResult, inspectedAt, remark, itemId },
      );
      return { assetInspectionItemId: Number(itemId) };
    });
  }
}

