import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Pager,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

type Action = { kind: 'link' | 'receive' | 'change' | 'complete'; row: Row };

const SIZE = 20;

export default function FnSfr02505Page({ role, notify }: PageProps) {
  const [inspectionType, setInspectionType] = useState('');
  const [approvalStatus, setApprovalStatus] = useState('');
  const [progressStatus, setProgressStatus] = useState('');
  const [page, setPage] = useState(0);
  const [action, setAction] = useState<Action | null>(null);
  const [form, setForm] = useState<Row>({});

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/asset-inspection-plans', role, undefined, {
        inspectionType,
        approvalStatus,
        progressStatus,
        page,
        size: SIZE,
      }),
    [inspectionType, approvalStatus, progressStatus, page],
  );

  function open(kind: Action['kind'], row: Row) {
    setForm({});
    setAction({ kind, row });
  }

  function setValue(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function finish(message: string) {
    notify(message);
    setAction(null);
    list.reload();
  }

  function reset() {
    setInspectionType('');
    setApprovalStatus('');
    setProgressStatus('');
    setPage(0);
  }

  async function link(row: Row) {
    await call('POST', `/asset-inspection-plans/${row.assetInspectionPlanId}/link`, role, {});
    finish('외부 자산실사 시스템과 연계했습니다.');
  }

  async function receive(row: Row) {
    if (!form.assetId) {
      throw new Error('자산을 선택해 주세요.');
    }
    await call('POST', '/asset-inspection-items/receive', role, {
      assetInspectionPlanId: row.assetInspectionPlanId,
      assetId: form.assetId,
      inspectionResult: form.inspectionResult,
      inspectedAt: form.inspectedAt,
      remark: form.remark,
    });
    finish('실사 결과를 저장했습니다.');
  }

  async function change() {
    if (!form.assetId || !form.changeType || !form.changeDate || !form.changeContent) {
      throw new Error('자산, 변동 유형, 변동 일자, 변동 내용을 모두 입력해 주세요.');
    }
    await call('POST', '/asset-changes', role, {
      assetId: form.assetId,
      changeType: form.changeType,
      changeDate: form.changeDate,
      changeContent: form.changeContent,
    });
    finish('자산 변동을 등록했습니다.');
  }

  async function complete(row: Row) {
    await call('POST', `/asset-inspection-plans/${row.assetInspectionPlanId}/complete`, role, {});
    finish('실사를 완료 처리했습니다.');
  }

  function renderDrawer() {
    if (!action) {
      return null;
    }
    const row = action.row;
    if (action.kind === 'link') {
      return (
        <Drawer title='외부 시스템 연계' onClose={() => setAction(null)}>
          <Form
            submit='연계 요청'
            note='승인된 실사계획의 대상을 외부 자산실사 시스템으로 보냅니다. 연계에 실패하면 오류 문장이 아래에 표시됩니다.'
            onSubmit={() => link(row)}
          />
        </Drawer>
      );
    }
    if (action.kind === 'receive') {
      return (
        <Drawer title='실사 결과 저장' onClose={() => setAction(null)}>
          <Form submit='결과 저장' onSubmit={() => receive(row)}>
            <Field label='자산 ID' required>
              <LookupSelect table='asset' role={role} value={form.assetId} onChange={(v) => setValue('assetId', v)} />
            </Field>
            <Field label='실사 결과'>
              <TextInput value={form.inspectionResult} onChange={(v) => setValue('inspectionResult', v)} />
            </Field>
            <Field label='실사 일시'>
              <DateInput value={form.inspectedAt} onChange={(v) => setValue('inspectedAt', v)} />
            </Field>
            <Field label='비고' wide>
              <TextInput multiline value={form.remark} onChange={(v) => setValue('remark', v)} />
            </Field>
          </Form>
        </Drawer>
      );
    }
    if (action.kind === 'change') {
      return (
        <Drawer title='차이 자산 변동 처리' onClose={() => setAction(null)}>
          <Form submit='변동 등록' onSubmit={change}>
            <Field label='자산' required>
              <LookupSelect table='asset' role={role} value={form.assetId} onChange={(v) => setValue('assetId', v)} />
            </Field>
            <Field label='변동 유형' required>
              <TextInput value={form.changeType} onChange={(v) => setValue('changeType', v)} />
            </Field>
            <Field label='변동 일자' required>
              <DateInput value={form.changeDate} onChange={(v) => setValue('changeDate', v)} />
            </Field>
            <Field label='변동 내용' required wide>
              <TextInput multiline value={form.changeContent} onChange={(v) => setValue('changeContent', v)} />
            </Field>
          </Form>
        </Drawer>
      );
    }
    return (
      <Drawer title='실사 완료 처리' onClose={() => setAction(null)}>
        <Form
          submit='완료 처리'
          danger
          note='완료 처리한 실사는 다시 진행 상태로 되돌릴 수 없습니다.'
          onSubmit={() => complete(row)}
        />
      </Drawer>
    );
  }

  const rows = list.data ? list.data.items : [];

  return (
    <div className='doc'>
      <section className='box'>
        <h2>자산실사 진행 현황</h2>
        <Filters onSearch={() => setPage(0)} onReset={reset}>
          <Field label='실사 유형'>
            <TextInput value={inspectionType} onChange={setInspectionType} />
          </Field>
          <Field label='승인 처리 상태'>
            <Select
              value={approvalStatus}
              onChange={setApprovalStatus}
              options={[
                ['신청', '신청'],
                ['승인', '승인'],
                ['승인 취소', '승인 취소'],
                ['반려', '반려'],
              ]}
            />
          </Field>
          <Field label='진행 상태'>
            <Select
              value={progressStatus}
              onChange={setProgressStatus}
              options={[
                ['진행', '진행'],
                ['완료', '완료'],
                ['취소', '취소'],
              ]}
            />
          </Field>
        </Filters>
        {list.error ? <p>{list.error}</p> : null}
        <Band total={list.data ? list.data.total : 0} />
        <DataTable
          rows={rows}
          empty='조건에 맞는 실사계획이 없습니다. 조건을 바꿔 다시 조회해 주세요.'
          columns={[
            { key: 'inspectionType', label: '실사 유형' },
            {
              key: 'period',
              label: '실사 기간',
              render: (r) => (
                <span>
                  <DateText value={r.startDate} /> ~ <DateText value={r.endDate} />
                </span>
              ),
            },
            { key: 'approvalStatus', label: '승인 처리 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            { key: 'progressStatus', label: '진행 상태', render: (r) => <Badge value={r.progressStatus} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => {
                const approved = r.approvalStatus === '승인';
                const running = r.progressStatus === '진행';
                return (
                  <span>
                    {approved && running ? (
                      <button className='ghost' onClick={() => open('link', r)}>연계</button>
                    ) : null}
                    {approved && running ? (
                      <button className='ghost' onClick={() => open('receive', r)}>결과 저장</button>
                    ) : null}
                    {approved && running ? (
                      <button className='ghost' onClick={() => open('change', r)}>변동 처리</button>
                    ) : null}
                    {running ? (
                      <button className='ghost' onClick={() => open('complete', r)}>완료</button>
                    ) : null}
                  </span>
                );
              },
            },
          ]}
        />
        <Pager
          page={list.data ? list.data.page : 0}
          size={SIZE}
          total={list.data ? list.data.total : 0}
          onPage={setPage}
        />
      </section>
      {renderDrawer()}
    </div>
  );
}
